"use client";

import "./dialog.css";

import React from "react";

import { Dialog as BaseDialog } from "@base-ui/react/dialog";
import { cn } from "tailwind-variants";

import { DialogContext, useDialogContext } from "./dialog.context";
import { dialogVariants, type DialogVariants } from "./dialog.variants";

export type DialogProps = DialogVariants & React.ComponentProps<typeof BaseDialog.Root>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogRoot = ({ children, size, ...props }: DialogProps) => {
  const slots = dialogVariants({ size });

  return (
    <DialogContext.Provider value={{ slots }}>
      <BaseDialog.Root {...props}>{children}</BaseDialog.Root>
    </DialogContext.Provider>
  );
};

export type DialogTriggerProps = React.ComponentProps<typeof BaseDialog.Trigger> & {
  render?: React.ReactElement;
  asChild?: boolean;
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogTrigger = ({
  className,
  children,
  render,
  asChild: _asChild,
  ...props
}: DialogTriggerProps) => {
  const { slots } = useDialogContext();
  const renderElement = render ?? (React.isValidElement(children) ? children : undefined);
  return (
    <BaseDialog.Trigger
      className={cn(slots.trigger(), className)}
      {...props}
      {...(renderElement ? { render: renderElement } : { children })}
    />
  );
};

export type DialogPortalProps = React.ComponentProps<typeof BaseDialog.Portal>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogPortal = (props: DialogPortalProps) => {
  return <BaseDialog.Portal {...props} />;
};

export type DialogBackdropProps = React.ComponentProps<typeof BaseDialog.Backdrop>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogBackdrop = ({ className, ...props }: DialogBackdropProps) => {
  const { slots } = useDialogContext();
  return <BaseDialog.Backdrop className={cn(slots.backdrop(), className)} {...props} />;
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogOverlay = DialogBackdrop;
export type DialogOverlayProps = DialogBackdropProps;

export type DialogPopupProps = React.ComponentProps<typeof BaseDialog.Popup>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogPopup = ({ className, ...props }: DialogPopupProps) => {
  const { slots } = useDialogContext();
  return <BaseDialog.Popup className={cn(slots.popup(), className)} {...props} />;
};

export type DialogTitleProps = React.ComponentProps<typeof BaseDialog.Title>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogTitle = ({ className, ...props }: DialogTitleProps) => {
  const { slots } = useDialogContext();
  return <BaseDialog.Title className={cn(slots.title(), className)} {...props} />;
};

export type DialogDescriptionProps = React.ComponentProps<typeof BaseDialog.Description>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogDescription = ({ className, ...props }: DialogDescriptionProps) => {
  const { slots } = useDialogContext();
  return <BaseDialog.Description className={cn(slots.description(), className)} {...props} />;
};

export type DialogCloseProps = React.ComponentProps<typeof BaseDialog.Close> & {
  render?: React.ReactElement;
  asChild?: boolean;
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const DialogClose = ({
  className,
  children,
  render,
  asChild: _asChild,
  ...props
}: DialogCloseProps) => {
  const { slots } = useDialogContext();
  const renderElement = render ?? (React.isValidElement(children) ? children : undefined);
  return (
    <BaseDialog.Close
      className={cn(slots.close(), className)}
      {...props}
      {...(renderElement ? { render: renderElement } : { children })}
    />
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const dialogVariants = tv({
  slots: {
    root: "dialog",
    trigger: "dialog__trigger",
    portal: "dialog__portal",
    backdrop: "dialog__backdrop",
    popup: "dialog__popup",
    title: "dialog__title",
    description: "dialog__description",
    close: "dialog__close",
  },
  variants: {
    size: {
      sm: {
        popup: "dialog__popup--sm",
      },
      md: {
        popup: "dialog__popup--md",
      },
      lg: {
        popup: "dialog__popup--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type DialogVariants = VariantProps<typeof dialogVariants>;

"use client";

import { createContext, useContext } from "react";

import { dialogVariants } from "./dialog.variants";

export type DialogContext = {
  slots: ReturnType<typeof dialogVariants>;
};

export const DialogContext = createContext<DialogContext | null>(null);

export const useDialogContext = () => {
  const context = useContext(DialogContext);
  return context ?? { slots: dialogVariants() };
};

.dialog__backdrop {
  @apply fixed inset-0 z-50 bg-black/80 transition-opacity duration-150 data-ending-style:opacity-0 data-starting-style:opacity-0;
}

.dialog__popup {
  @apply fixed top-1/2 left-1/2 z-50 flex w-full max-w-lg -translate-x-1/2 -translate-y-1/2 flex-col gap-4 border border-border bg-background p-6 shadow-lg duration-100 ease-out transition-[scale,opacity] rounded-lg text-foreground data-ending-style:scale-95 data-ending-style:opacity-0 data-starting-style:scale-95 data-starting-style:opacity-0;
}

.dialog__popup--sm {
  @apply max-w-sm;
}

.dialog__popup--md {
  @apply max-w-lg;
}

.dialog__popup--lg {
  @apply max-w-2xl;
}

.dialog__title {
  @apply text-lg font-semibold leading-none tracking-tight;
}

.dialog__description {
  @apply text-sm text-muted-foreground;
}

.dialog__close {
  @apply inline-flex items-center justify-center rounded-md border border-input bg-background px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50;
}

import {
  DialogBackdrop,
  DialogClose,
  DialogDescription,
  DialogOverlay,
  DialogPopup,
  DialogPortal,
  DialogRoot,
  DialogTitle,
  DialogTrigger,
} from "./dialog";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/dialog/content.md
 */
export const Dialog = {
  Backdrop: DialogBackdrop,
  Close: DialogClose,
  Description: DialogDescription,
  Overlay: DialogOverlay,
  Popup: DialogPopup,
  Portal: DialogPortal,
  Root: DialogRoot,
  Title: DialogTitle,
  Trigger: DialogTrigger,
};

export {
  DialogBackdrop,
  DialogClose,
  DialogDescription,
  DialogOverlay,
  DialogPopup,
  DialogPortal,
  DialogRoot,
  DialogTitle,
  DialogTrigger,
};

export type {
  DialogBackdropProps,
  DialogCloseProps,
  DialogDescriptionProps,
  DialogOverlayProps,
  DialogPopupProps,
  DialogPortalProps,
  DialogProps,
  DialogTitleProps,
  DialogTriggerProps,
} from "./dialog";
export { DialogContext, useDialogContext } from "./dialog.context";
export { type DialogVariants, dialogVariants } from "./dialog.variants";
